# Look for rectangular areas of uniform color (excluding 5)
def find_rectangles(grid, ignore_bg=5):
    """Find large rectangular regions of uniform color"""
    rows, cols = len(grid), len(grid[0])
    rectangles = []

    for color in range(10):
        if color == ignore_bg:
            continue
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color:
                    # Check if this starts a rectangle
                    height = 0
                    while r + height < rows and grid[r+height][c] == color:
                        height += 1
                    width = 0
                    while c + width < cols and grid[r][c+width] == color:
                        width += 1

                    # Check if it's a perfect rectangle
                    is_rect = True
                    for dr in range(height):
                        for dc in range(width):
                            if grid[r+dr][c+dc] != color:
                                is_rect = False
                                break
                        if not is_rect:
                            break

                    if is_rect:
                        # Only record if reasonably sized (>= 4 cells)
                        if height * width >= 4:
                            rect = (r, c, height, width, color)
                            # Check if already recorded
                            found = False
                            for existing in rectangles:
                                if existing[0] == r and existing[1] == c and existing[2] == height and existing[3] == width and existing[4] == color:
                                    found = True
                                    break
                            if not found:
                                rectangles.append(rect)

    return rectangles

rects = find_rectangles(input_grid)
print(f"\nFound {len(rects)} rectangular regions")
