# Let me look at object positions and try to understand the pattern
# First let's identify all "objects" - connected components of non-5 colors

from collections import deque

def find_connected_components(grid, ignore_color=5):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != ignore_color and not visited[r][c]:
                component = []
                queue = deque([(r, c, grid[r][c])])  # (row, col, color)
                visited[r][c] = True
                while queue:
                    cr, cc, color = queue.popleft()
                    component.append((cr, cc, color))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != ignore_color and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc, grid[nr][nc]))
                components.append(component)
    return components

# Wait, the different colored cells might not be connected...
# Let me reconsider - maybe we should look at regions of same color

def find_regions_by_color(grid, ignore_bg=5):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    regions_by_color = {}  # color -> list of components

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color == ignore_bg:
                continue
            if visited[r][c]:
                continue
            # BFS for this cell's color
            component = []
            queue = deque([(r, c)])
            visited[r][c] = True
            while queue:
                cr, cc = queue.popleft()
                component.append((cr, cc))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and not visited[nr][nc]:
                        visited[nr][nc] = True
                        queue.append((nr, nc))
            if color not in regions_by_color:
                regions_by_color[color] = []
            regions_by_color[color].append(component)

    return regions_by_color

regions = find_regions_by_color(input_grid, ignore_bg=5)

