# Let me try a projection approach
# What if we project from each corner and combine?

def project_from_corner(grid, direction):
    """Project toward center from a corner"""
    rows, cols = len(grid), len(grid[0])
    result = []

    for r in range(rows):
        row_proj = []
        for c in range(cols):
            # Find the first non-5 cell when projecting from the corner
            # direction determines which corner
            valid = False

            if direction == 'tl':  # top-left projection
                for tr in range(r, max(0, r-(c))):
                    if tr >= 0 and tc := max(0, tr):
                        if grid[tr][tc] != 5:
                            row_proj.append(grid[tr][tc])
                            valid = True
                            break
                    if tr + c < 21 and grid[r][c] != 5:
                        row_proj.append(grid[tr][c])
                        valid = True
                        break

            if not valid:
                row_proj.append(0)

        result.append(row_proj)
    return result

# Let me simplify - just check if each cell has a non-5 neighbor in a specific direction
from collections import deque

def check_corner_projection(grid, target_color=5):
    rows, cols = len(grid), len(grid[0])
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            # Check all directions for non-target color
            # Returns the direction of the nearest non-5 cell
            best_dir = None
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                while 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] != target_color:
                        best_dir = (nr, nc)
                        break
                    nr += dr
                    nc += dc

            if best_dir:
                tr, tc = best_dir
                result[r][c] = input_grid[tr][tc]
            else:
                result[r][c] = 0

    return result

