# Try: For each cell, find nearest non-5 neighbor and output that color
def find_nearest_non5(grid, target=5):
    rows, cols = len(grid), len(grid[0])
    result = []

    for r in range(rows):
        row_result = []
        for c in range(cols):
            if grid[r][c] != target:
                row_result.append(grid[r][c])
            else:
                # Find nearest non-5 neighbor
                best_color = None
                best_dist = float('inf')
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r+dr, c+dc
                    while 0 <= nr < rows and 0 <= nc < cols:
                        candidate = grid[nr][nc]
                        dist = abs(nr - r) + abs(nc - c)
                        if candidate != target:
                            if dist < best_dist:
                                best_dist = dist
                                best_color = candidate
                            break
                        nr += dr
                        nc += dc
                row_result.append(best_color if best_color else 0)
        result.append(row_result)
    return result

# Actually this is what I want - each 5 gets replaced by nearest non-5
proj = find_nearest_non5(input_grid, target=5)
print("Replace 5 with nearest non-5:")
for r in range(10):
    print(' '.join(str(o) for o in proj[r]))

